style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url("https://media.tenor.com/JrZ3JMdF3m0AAAAC/hello-kitty-room-pixel.gif");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-color: black !important; /* Cor de fundo caso o gif falhe */
    color: white !important;
  }

  /* Torna o fundo visível por baixo do conteúdo */
  .container-main, .container, .game-details, .section, header, footer {
    background-color: rgba(0, 0, 0, 0.4) !important; /* Fundo translúcido */
  }
}
